<script lang="ts">
 import {onDestroy} from 'svelte';import {scenes} from '../domain';import {companion,updateData,notify} from '../state.svelte';import {sceneMotion} from '../art';
 import {inspectSceneFile,putSceneMedia,getSceneMedia,deleteSceneMedia,sceneAccept,type LocalScene} from '../sceneLibrary';
 import SceneArt from './SceneArt.svelte';import PixelRoom from './PixelRoom.svelte';import PulseHeart from './PulseHeart.svelte';import ConfirmDialog from './ConfirmDialog.svelte';
 let selected=$state(companion.data.preferences.scene),filter=$state('全部'),busy=$state(false),error=$state(''),fileInput:HTMLInputElement,removing=$state<LocalScene|null>(null),alive=true;
 onDestroy(()=>alive=false);
 let library=$derived([...scenes,...(companion.data.sceneLibrary||[])]),preview=$derived(library.find(s=>s.id===selected)||library[0]);
 let visible=$derived(library.filter(s=>filter==='全部'||s.time===filter||filter==='收藏'&&companion.data.preferences.favorites.includes(s.id)));
 async function importFile(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];fileInput.value='';if(!file)return;busy=true;error='';let stored='';try{if((companion.data.sceneLibrary?.length||0)>=20)throw Error('最多保留 20 份本地背景，删除一些后再导入。');if((companion.data.sceneLibrary||[]).reduce((n,s)=>n+s.bytes,0)+file.size>250*1024*1024)throw Error('本地背景总计需小于 250 MB，请先删除一些背景。');const scene=await inspectSceneFile(file);if(!alive||companion.locked)throw Error('页面已离开，请在场景页重新导入。');await putSceneMedia(scene.id,file);stored=scene.id;if(!alive||companion.locked)throw Error('页面已离开，请在场景页重新导入。');updateData(data=>(data.sceneLibrary??=[]).push(scene));stored='';selected=scene.id;filter='我的';notify('背景已存入本地场景库，可以预览后应用。');}catch(e){if(stored)await deleteSceneMedia(stored).catch(()=>{});if(alive)error=String(e).replace(/^Error: /,'');}finally{if(alive)busy=false;}}
 function favorite(id:string,liked:boolean){try{updateData(data=>data.preferences.favorites=liked?[...new Set([...data.preferences.favorites,id])]:data.preferences.favorites.filter(s=>s!==id));}catch(e){notify(String(e));}}
 async function remove(){const scene=removing;if(!scene)return;if(companion.locked)throw Error('请先解锁应用。');const blob=await getSceneMedia(scene.id);await deleteSceneMedia(scene.id);try{updateData(data=>{data.sceneLibrary=(data.sceneLibrary||[]).filter(s=>s.id!==scene.id);data.preferences.favorites=data.preferences.favorites.filter(id=>id!==scene.id);if(data.preferences.scene===scene.id)data.preferences.scene='warm_room';});}catch(e){if(blob)await putSceneMedia(scene.id,blob);throw e;}if(selected===scene.id)selected=companion.data.preferences.scene;removing=null;notify('本地背景已删除。');}
 function apply(){try{updateData(data=>data.preferences.scene=selected);notify('窗外的风景已换好，回到对话小屋看看吧。');}catch(e){notify(String(e));}}
</script>
<div class="scene-toolbar"><div class="filter-tabs scene-filters" aria-label="场景分类">{#each ['全部','日间','夜晚','自然','我的','收藏'] as item}<button class:chosen={filter===item} aria-pressed={filter===item} onclick={()=>filter=item}>{item}</button>{/each}</div><div class="scene-import"><input bind:this={fileInput} class="sr-only" id="scene-file" type="file" tabindex="-1" accept={sceneAccept} aria-label="选择本地背景文件" onchange={importFile} disabled={busy}/><button type="button" class="xy-btn" disabled={busy} onclick={()=>fileInput.click()}><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/></svg>{busy?'正在整理背景…':'导入图片或视频'}</button><small>只存当前浏览器 · 视频静音播放</small></div></div>
{#if error}<p class="scene-import-error" role="alert">{error}</p>{/if}
<div class="scenes-layout"><div class="scene-grid">{#each visible as scene (scene.id)}<article class="scene-card" class:chosen={selected===scene.id}><button class="scene-preview-button" aria-label={'预览'+scene.name} onclick={()=>selected=scene.id}><SceneArt scene={scene.id} label={scene.name+'像素窗景'}/><div><h3>{scene.name}</h3><p>{scene.time} · {companion.data.preferences.scene===scene.id?'当前使用':'点击预览'}</p><p class="scene-motion-caption">{sceneMotion[scene.id]||('kind' in scene&&scene.kind==='video'?'静音循环 · 天气独立叠加':'轻柔景深 · 天气独立叠加')}</p></div></button><div class="scene-card-actions"><PulseHeart liked={companion.data.preferences.favorites.includes(scene.id)} label={scene.name} reduced={companion.data.preferences.reduceMotion} onchange={liked=>favorite(scene.id,liked)}/>{#if 'kind' in scene}<button type="button" class="text-button danger-text" aria-label={'删除背景'+scene.name} onclick={()=>removing=scene as LocalScene}>删除</button>{/if}</div></article>{/each}
{#if !visible.length}<div class="xy-panel module-empty">{filter==='我的'?'导入一张喜欢的图片，或一段窗外的视频。':'还没有收藏场景，挑一个喜欢的角落吧。'}</div>{/if}</div>
<aside class="xy-panel scene-detail"><h2>窗外，现在是这样</h2><div class="scene-detail-preview"><PixelRoom scene={selected} avatar={companion.data.preferences.avatar} reduced={companion.data.preferences.reduceMotion} compact/></div><h3>{preview.name}</h3><p>{preview.description}</p><button class="xy-btn primary" onclick={apply}>应用这个场景</button>{#if 'kind' in preview}<p class="quiet-note">本地文件不会上传；清除浏览器数据后需重新导入。图片不超过 20 MB，视频不超过 100 MB。</p>{/if}</aside></div>
{#if removing}<ConfirmDialog destructive title="删除这份本地背景？" description="会删除此浏览器内的文件与收藏；正在使用时回到晴昼小屋。原电脑文件不会被删除。" confirmText="删除背景" onclose={()=>removing=null} onconfirm={remove}/>{/if}
<style>.scene-toolbar{display:flex;align-items:center;justify-content:space-between;gap:24px;margin:4px 0 18px}.scene-import{display:grid;justify-items:end;gap:7px}.scene-import small{font-size:12px;color:var(--xy-secondary)}.scene-filters{margin:0}.scene-import-error{padding:12px 16px;background:var(--xy-panel);border:1px solid var(--xy-border);color:var(--xy-ink);border-radius:8px;line-height:1.8}.scene-card-actions{display:flex;align-items:center;justify-content:flex-end;gap:12px;padding:0 12px 12px}.scene-card-actions :global(.pulse-heart){margin:0}.scene-card-actions .text-button{min-height:40px}.scene-import>.xy-btn{min-height:44px}</style>
